#include "web/dashboard_routes.h"

#include "common/calendar.h"
#include "common/stats.h"
#include "web/dashboard.h"
#include "dashboard.page.h" // generated by pagec

#include <ctime>

namespace purr::web {

std::string renderDashboard(const Site& site)
{
    std::time_t now = std::time(nullptr);
    Config cfg = site.config();
    Dashboard view = buildDashboard(loadStats(site.paths.db, cal::localDay(now), circumferences(cfg)), cfg.wheel, now);
    view.configErrors = cfg.errors;
    view.units = cfg.editable.units;
    std::string html;
    html.reserve(64 * 1024);
    pages::dashboard(html, view);
    return html;
}

void addDashboardRoutes(const Site& site, httplib::Server& server)
{
    server.Get("/", [&](const httplib::Request&, httplib::Response& res) {
        res.set_content(renderDashboard(site), "text/html; charset=utf-8");
        res.set_header("Cache-Control", "no-store");
    });
    server.Get("/api/stats", [&](const httplib::Request&, httplib::Response& res) {
        res.set_content(renderApi(site), "application/json");
        res.set_header("Cache-Control", "no-store");
    });
    server.Get("/healthz", [](const httplib::Request&, httplib::Response& res) { res.set_content("ok\n", "text/plain"); });
}

} // namespace purr::web
